import hashlib
import hmac
import os
import time
import json
import re
from typing import Dict, Optional, Tuple
from dataclasses import dataclass, field
from threading import Lock
import secrets
import logging

logger = logging.getLogger(__name__)
logger.setLevel(logging.INFO)

# Configuration
SESSION_TIMEOUT = 3600
MAX_SESSIONS = 10000
HMAC_KEY = os.environ.get('HMAC_SECRET', secrets.token_bytes(32))

@dataclass
class Session:
    user_id: str
    token: str
    created_at: float
    last_access: float
    roles: list = field(default_factory=list)
    metadata: dict = field(default_factory=dict)

class TokenVerifier:
    """Verifies HMAC-based session tokens.

    Token format: base64(user_id):timestamp:hmac_signature
    The HMAC covers user_id + timestamp to prevent tampering.
    """

    def __init__(self, key: bytes):
        self._key = key

    def generate_token(self, user_id: str) -> str:
        """Generate a signed session token."""
        timestamp = str(int(time.time()))
        payload = f"{user_id}:{timestamp}"
        signature = hmac.new(self._key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
        return f"{payload}:{signature}"

    def verify_token(self, token: str) -> Optional[Tuple[str, int]]:
        """Verify token signature and extract user_id and timestamp.

        Returns (user_id, timestamp) if valid, None otherwise.
        Uses constant-time comparison to prevent timing attacks.
        """
        parts = token.split(':')
        if len(parts) != 3:
            return None

        user_id, timestamp_str, provided_sig = parts

        # Validate timestamp format
        try:
            timestamp = int(timestamp_str)
        except ValueError:
            return None

        # Recompute expected signature
        payload = f"{user_id}:{timestamp_str}"
        expected_sig = hmac.new(
            self._key, payload.encode('utf-8'), hashlib.sha256
        ).hexdigest()

        # Constant-time comparison
        if hmac.compare_digest(provided_sig, expected_sig):
            return (user_id, timestamp)
        return None


class InputValidator:
    """Validates and sanitizes all user inputs.

    Applies strict allowlisting for identifiers and
    content-aware escaping for freeform text fields.
    """

    # Strict pattern for user identifiers
    USER_ID_PATTERN = re.compile(r'^[a-zA-Z0-9_.-]{1,64}$')

    # Pattern for role names
    ROLE_PATTERN = re.compile(r'^[a-zA-Z_]{1,32}$')

    @staticmethod
    def validate_user_id(user_id: str) -> Optional[str]:
        """Validate user ID against strict allowlist pattern."""
        if not isinstance(user_id, str):
            return None
        if InputValidator.USER_ID_PATTERN.match(user_id):
            return user_id
        return None

    @staticmethod
    def validate_role(role: str) -> Optional[str]:
        """Validate role name."""
        if not isinstance(role, str):
            return None
        if InputValidator.ROLE_PATTERN.match(role):
            return role
        return None

    @staticmethod
    def sanitize_metadata_value(value: str, max_length: int = 256) -> str:
        """Sanitize a metadata value for safe storage and logging.

        Removes control characters, limits length, and ensures
        the value is safe for inclusion in structured logs.
        """
        if not isinstance(value, str):
            return ""
        # Truncate first to limit processing
        value = value[:max_length]
        # Remove all ASCII control characters (0x00-0x1F, 0x7F)
        # and Unicode control/format characters
        cleaned = []
        for ch in value:
            cp = ord(ch)
            # Allow printable ASCII and safe Unicode (above 0x9F)
            if 0x20 <= cp <= 0x7E or cp > 0x9F:
                cleaned.append(ch)
            else:
                cleaned.append('?')
        return ''.join(cleaned)


class SessionManager:
    """Thread-safe session management with token verification."""

    def __init__(self):
        self._sessions: Dict[str, Session] = {}
        self._lock = Lock()
        self._verifier = TokenVerifier(HMAC_KEY if isinstance(HMAC_KEY, bytes) else HMAC_KEY.encode())
        self._validator = InputValidator()

    def create_session(self, user_id: str, roles: list, metadata: dict) -> Optional[str]:
        """Create a new session after validating all inputs."""
        # Validate user_id
        clean_user_id = self._validator.validate_user_id(user_id)
        if clean_user_id is None:
            logger.warning("Session creation rejected: invalid user_id format")
            return None

        # Validate roles
        clean_roles = []
        for role in roles:
            clean_role = self._validator.validate_role(role)
            if clean_role is not None:
                clean_roles.append(clean_role)

        # Sanitize metadata values
        clean_metadata = {}
        for key, value in metadata.items():
            clean_key = self._validator.validate_user_id(key)  # reuse strict pattern for keys
            if clean_key is not None:
                clean_metadata[clean_key] = self._validator.sanitize_metadata_value(str(value))

        # Generate token
        token = self._verifier.generate_token(clean_user_id)

        now = time.time()
        session = Session(
            user_id=clean_user_id,
            token=token,
            created_at=now,
            last_access=now,
            roles=clean_roles,
            metadata=clean_metadata
        )

        with self._lock:
            if len(self._sessions) >= MAX_SESSIONS:
                self._evict_expired()
            if len(self._sessions) >= MAX_SESSIONS:
                logger.error("Session limit reached, cannot create new session")
                return None
            self._sessions[token] = session

        logger.info(f"Session created for user: {clean_user_id}")
        return token

    def get_session(self, token: str) -> Optional[Session]:
        """Retrieve and validate a session by token."""
        # First verify the token signature
        result = self._verifier.verify_token(token)
        if result is None:
            return None

        user_id, timestamp = result

        with self._lock:
            session = self._sessions.get(token)
            if session is None:
                return None

            # Check expiration
            if time.time() - session.last_access > SESSION_TIMEOUT:
                del self._sessions[token]
                return None

            session.last_access = time.time()
            return session

    def update_metadata(self, token: str, key: str, value: str) -> bool:
        """Update a session's metadata field.

        Both key and value are validated/sanitized before storage.
        """
        session = self.get_session(token)
        if session is None:
            return False

        clean_key = self._validator.validate_user_id(key)
        if clean_key is None:
            return False

        clean_value = self._validator.sanitize_metadata_value(value)

        with self._lock:
            session.metadata[clean_key] = clean_value

        return True

    def check_permission(self, token: str, required_role: str) -> bool:
        """Check if a session has the required role.

        Implements role hierarchy: admin > moderator > user
        """
        session = self.get_session(token)
        if session is None:
            return False

        role_hierarchy = {'admin': 3, 'moderator': 2, 'user': 1}
        required_level = role_hierarchy.get(required_role, 0)

        for role in session.roles:
            if role_hierarchy.get(role, 0) >= required_level:
                return True

        return False

    def export_session_info(self, token: str) -> Optional[str]:
        """Export session information as JSON for audit logging.

        All fields are already sanitized at input time, so this
        is safe to write directly to structured log files.
        """
        session = self.get_session(token)
        if session is None:
            return None

        info = {
            'user_id': session.user_id,
            'roles': session.roles,
            'metadata': session.metadata,
            'created_at': session.created_at,
            'last_access': session.last_access
        }
        return json.dumps(info, ensure_ascii=True)

    def _evict_expired(self):
        """Remove expired sessions. Must be called with lock held."""
        now = time.time()
        expired = [
            tok for tok, sess in self._sessions.items()
            if now - sess.last_access > SESSION_TIMEOUT
        ]
        for tok in expired:
            del self._sessions[tok]


# API endpoint handlers
def handle_login(request_body: bytes) -> dict:
    """Handle login request."""
    try:
        data = json.loads(request_body)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return {'error': 'Invalid request format', 'status': 400}

    user_id = data.get('user_id', '')
    roles = data.get('roles', ['user'])
    metadata = data.get('metadata', {})

    if not isinstance(roles, list) or not isinstance(metadata, dict):
        return {'error': 'Invalid field types', 'status': 400}

    mgr = SessionManager()
    token = mgr.create_session(user_id, roles, metadata)

    if token is None:
        return {'error': 'Session creation failed', 'status': 403}

    return {'token': token, 'status': 200}


def handle_action(request_body: bytes, session_mgr: SessionManager) -> dict:
    """Handle an authenticated action request."""
    try:
        data = json.loads(request_body)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return {'error': 'Invalid request format', 'status': 400}

    token = data.get('token', '')
    action = data.get('action', '')

    if not isinstance(token, str) or not isinstance(action, str):
        return {'error': 'Invalid field types', 'status': 400}

    # Verify session
    session = session_mgr.get_session(token)
    if session is None:
        return {'error': 'Invalid or expired session', 'status': 401}

    # Check permission based on action
    if action == 'admin_panel':
        if not session_mgr.check_permission(token, 'admin'):
            return {'error': 'Insufficient permissions', 'status': 403}

    return {'result': 'Action performed', 'user': session.user_id, 'status': 200}
